import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { PagoCargaMasiva } from '../models/pago.carga.masiva';
import { firstValueFrom } from 'rxjs';

export interface CargaRevisada extends PagoCargaMasiva{
  coincidencia_escrita?:number;
  [key:string]: any;
}

export interface CargaMasivaRevision{
  correctos:{
    exactos: CargaRevisada[];
    potenciales: CargaRevisada[];
    no_encontrados: CargaRevisada[];
  };
  datos_insuficientes:[];
  tipo_incorrecto:any[];
}

@Injectable({
  providedIn: 'any'
})
export class PagoCargaMasivaService extends SuperService<PagoCargaMasiva> {
  protected override model: string ="pagos_cargas_masivas";
  protected override columns: (keyof PagoCargaMasiva)[] = [
    'id',
    'descripcion',
    'referencia_de_cliente',
    'tipo_de_trn',
    'fecha_valor',
    'importe_de_credito',
    'hora_de_cargo_o_abono',
    'fecha_del_apunte',
    'fecha_abono',
    'nota',
    'credito_id',
    'aplicado',
    'usuario_id',
    'comprobante_url',
    'pagos_layout_id'
];


  constructor(injector: Injector){
    super(injector)
  }

  async revisar(data:any[]){
    const res= await firstValueFrom(this.api.post('api/revision/pagos_cargas_masivas',data))
    console.log(res.data)
    return res.data as CargaMasivaRevision
  }

  async asociarCargaMasiva(cargaMasiva:PagoCargaMasiva){
    const data={ 
      pago_masivo_id:cargaMasiva.id, 
      credito_id:cargaMasiva.credito_id,
      nota: cargaMasiva.nota,
    }
    const res= await firstValueFrom(this.api.post('api/asociar/pagos_cargas_masivas',data))
    console.log(res)
    return res.status
  }
}